package dev.pocketengine.store;

import android.app.Application;import android.database.sqlite.SQLiteDatabase;
import dev.pocketengine.testutil.HttpServer;
import dev.pocketengine.core.*;import dev.pocketengine.runtime.ModelGateway;import dev.pocketengine.runtime.usage.*;
import dev.pocketengine.media.voice.*;
import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
import static org.junit.Assert.*;

/** Actual original SQL/Capture and loopback Gateway. Not a provider bill, account login or audio device. */
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,manifest=Config.NONE,application=Application.class) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class NativeInferenceUsageJourneyTest {
 private static String id(){return UUID.randomUUID().toString();}
 private static SQLiteDatabase database(TaskStore tasks)throws Exception{var f=TaskStore.class.getDeclaredField("db");f.setAccessible(true);return (SQLiteDatabase)f.get(tasks);}
 private static final class Fixture implements AutoCloseable{
  final Application android=RuntimeEnvironment.getApplication();final TaskStore tasks;
  Fixture()throws Exception{android.deleteDatabase("pocket-world.db");tasks=new TaskStore(android);}
  public void close()throws Exception{SQLiteDatabase db=database(tasks);if(db.isOpen())db.close();}
 }
 private static ModelConfig config(){return new ModelConfig("https://fixture.invalid/v1","fixture-native-not-a-real-secret","fixture-model",false,8,5);}
 private static JSONObject response(String responseId)throws Exception{return new JSONObject().put("id",responseId).put("status","completed").put("model","actual-voice-model").put("output",new JSONArray().put(new JSONObject().put("audio","AUDIO-MUST-NOT-PERSIST").put("transcript","TRANSCRIPT-MUST-NOT-PERSIST"))).put("usage",new JSONObject().put("input_tokens",31).put("output_tokens",17).put("total_tokens",48).put("input_token_details",new JSONObject().put("cached_tokens",8).put("text_tokens",7).put("audio_tokens",24)).put("output_token_details",new JSONObject().put("text_tokens",4).put("audio_tokens",13)));}
 private static RealtimeVoiceProfile profile()throws Exception{return new RealtimeVoiceProfile("wss://voice.example.invalid/realtime","selected-realtime","alloy",1);}
 @Test public void nativeAccountingHasOriginalDurableCallButNoToolOrResumePermission()throws Exception{try(Fixture f=new Fixture()){
  RunControl original=new RunControl();try(NativeInferenceWork work=NativeInferenceWork.open(f.tasks,TaskStore.NativeInferenceKind.CONNECTION_TEST,id(),original)){
   JSONObject locator=work.reference();String task=locator.getString("taskId");assertTrue(locator.getBoolean("accountingOnly"));assertFalse(locator.getBoolean("executionAuthorized"));assertTrue(original.matchesHostRun(task,locator.getString("runId"),locator.getInt("epoch")));
   InferenceCapture capture=new InferenceCapture(config(),original,work.target());capture.dispatch();capture.dispatch();assertEquals(1,f.tasks.inferenceUsage(task).getInt("attempts"));capture.usage.observe(new JSONObject().put("usage",new JSONObject().put("prompt_tokens",2).put("completion_tokens",3).put("total_tokens",5)),ProviderUsage.Stage.FINAL);capture.finish(InferenceReceipt.Outcome.COMPLETED);capture.finish(InferenceReceipt.Outcome.COMPLETED);work.completed();
   JSONObject evidence=f.tasks.get(task,false);assertEquals("inference",evidence.getString("kind"));assertEquals("completed",evidence.getString("status"));assertEquals(0,evidence.getJSONArray("operations").length());assertThrows(SecurityException.class,()->f.tasks.startAttempt(task,"capabilities",8));
   JSONObject grant;try(var row=database(f.tasks).rawQuery("SELECT grant_json FROM runs WHERE run_id=?",new String[]{locator.getString("runId")})){assertTrue(row.moveToFirst());grant=new JSONObject(row.getString(0));}assertEquals(0,grant.getInt("remainingOperations"));assertFalse(grant.has("allowedTools"));
   assertEquals(0,f.tasks.taskSummaryPage("",40).getJSONArray("tasks").length());JSONObject page=f.tasks.nativeInferenceUsagePage("",40);assertEquals(task,page.getJSONArray("tasks").getJSONObject(0).getString("id"));assertFalse(page.getBoolean("executionAuthorized"));assertEquals(1,f.tasks.inferenceUsage(task).getInt("attempts"));
  }
 }}
 @Test public void anExistingOriginalTaskKeepsAttributionAndIsNotEndedOrReplacedByVoiceUsage()throws Exception{try(Fixture f=new Fixture()){
  JSONObject task=f.tasks.startAttempt(f.tasks.createCapabilityTask("原真实任务",id()).getString("id"),"capabilities",8);RunControl original=new RunControl();original.bindHostRun(task.getString("id"),task.getString("runId"),task.getInt("coordinatorEpoch"));int count=f.tasks.list().length();String status=f.tasks.get(task.getString("id"),false).getString("status");
  try(NativeInferenceWork work=NativeInferenceWork.open(f.tasks,TaskStore.NativeInferenceKind.VOICE_TURN,id(),original)){
   assertFalse(work.reference().getBoolean("accountingOnly"));assertEquals(task.getString("id"),work.target().context.taskId);assertEquals(task.getString("runId"),work.target().context.runId);assertEquals(InferenceReceipt.Purpose.VOICE_TURN,work.target().context.purpose);
   InferenceCapture capture=new InferenceCapture(config(),original,work.target());capture.dispatch();capture.finish(InferenceReceipt.Outcome.COMPLETED);work.completed();
  }
  assertEquals(count,f.tasks.list().length());assertEquals(status,f.tasks.get(task.getString("id"),false).getString("status"));assertEquals(1,f.tasks.inferenceUsage(task.getString("id")).getInt("attempts"));
 }}
 @Test public void reopeningUnfinishedNativeUsageKeepsStartedUnknownAndNeverCreatesResumeGrant()throws Exception{
  try(Fixture f=new Fixture()){
   RunControl original=new RunControl();NativeInferenceWork work=NativeInferenceWork.open(f.tasks,TaskStore.NativeInferenceKind.VOICE_TURN,id(),original);JSONObject ref=work.reference();InferenceCapture capture=new InferenceCapture(config(),original,work.target());capture.dispatch();database(f.tasks).close();
   TaskStore reopened=new TaskStore(f.android);try{JSONObject saved=reopened.get(ref.getString("taskId"),false);assertEquals("interrupted",saved.getString("status"));JSONObject usage=reopened.inferenceUsage(ref.getString("taskId"));assertEquals(1,usage.getInt("attempts"));assertEquals("STARTED",usage.getJSONArray("receipts").getJSONObject(0).getString("outcome"));assertTrue(usage.getJSONArray("receipts").getJSONObject(0).getJSONObject("usage").getJSONObject("counters").getJSONObject("TOTAL").isNull("value"));assertThrows(SecurityException.class,()->reopened.startAttempt(ref.getString("taskId"),"capabilities",8));}finally{database(reopened).close();}
  }
 }
 @Test public void realtimeResponseDedupIsOnlySessionLocalAndNeverPersistsAudioOrTranscript()throws Exception{try(Fixture f=new Fixture()){
  String firstTask,firstCall;try(RealtimeInferenceAccounting accounting=RealtimeInferenceAccounting.open(f.tasks,profile(),"fixture-private-voice-key",id())){
   firstTask=accounting.reference().getString("taskId");JSONObject created=new JSONObject().put("id","response_same");accounting.created(created);accounting.created(created);JSONObject done=response("response_same");accounting.done(done);accounting.done(new JSONObject(done.toString()));
   JSONObject usage=f.tasks.inferenceUsage(firstTask);assertEquals(1,usage.getInt("attempts"));JSONObject receipt=usage.getJSONArray("receipts").getJSONObject(0);firstCall=receipt.getString("callId");assertEquals("server_response_observed",receipt.getJSONObject("route").getString("requestOrigin"));assertEquals("REALTIME",receipt.getJSONObject("context").getString("purpose"));assertEquals(31,receipt.getJSONObject("usage").getJSONObject("counters").getJSONObject("INPUT").getLong("value"));assertFalse(f.tasks.get(firstTask,false).toString().contains("MUST-NOT-PERSIST"));assertThrows(SecurityException.class,()->accounting.done(response("response_same").put("usage",new JSONObject().put("input_tokens",99))));
  }
  try(RealtimeInferenceAccounting another=RealtimeInferenceAccounting.open(f.tasks,profile(),"fixture-private-voice-key",id())){another.created(new JSONObject().put("id","response_same"));another.done(response("response_same"));String secondTask=another.reference().getString("taskId");assertNotEquals(firstTask,secondTask);assertNotEquals(firstCall,f.tasks.inferenceUsage(secondTask).getJSONArray("receipts").getJSONObject(0).getString("callId"));assertEquals(1,f.tasks.inferenceUsage(firstTask).getInt("attempts"));}
 }}
 @Test public void realtimeDisconnectRetainsObservedFailedUnknownInsteadOfFreeZeroOrAutomaticRetry()throws Exception{try(Fixture f=new Fixture()){
  RealtimeInferenceAccounting accounting=RealtimeInferenceAccounting.open(f.tasks,profile(),"fixture-private-voice-key",id());String task=accounting.reference().getString("taskId");accounting.created(new JSONObject().put("id","response_partial"));accounting.close("network_unconfirmed");JSONObject receipt=f.tasks.inferenceUsage(task).getJSONArray("receipts").getJSONObject(0);assertEquals("FAILED",receipt.getString("outcome"));assertTrue(receipt.getJSONObject("usage").getJSONObject("counters").getJSONObject("OUTPUT").isNull("value"));assertEquals(1,f.tasks.inferenceUsage(task).getInt("attempts"));assertEquals("failed",f.tasks.get(task,false).getString("status"));
 }}
 @Test public void actualGatewayConnectionTestWritesItsRealHttpReceiptToNativeSession()throws Exception{try(Fixture f=new Fixture()){
  AtomicInteger posts=new AtomicInteger();HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);ExecutorService worker=Executors.newSingleThreadExecutor();server.setExecutor(worker);server.createContext("/",exchange->{try{posts.incrementAndGet();exchange.getRequestBody().readAllBytes();byte[] body="{\"choices\":[{\"message\":{\"role\":\"assistant\",\"content\":\"OK\"},\"finish_reason\":\"stop\"}],\"usage\":{\"prompt_tokens\":2,\"completion_tokens\":1,\"total_tokens\":3}}".getBytes(StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","application/json");exchange.sendResponseHeaders(200,body.length);exchange.getResponseBody().write(body);}finally{exchange.close();}});server.start();
  try{RunControl original=new RunControl();try(NativeInferenceWork work=NativeInferenceWork.open(f.tasks,TaskStore.NativeInferenceKind.CONNECTION_TEST,id(),original)){
   JSONObject result=ModelGateway.testConnection(new ModelConfig("http://127.0.0.1:"+server.getAddress().getPort(),"fixture-private-key","actual-http-model",false,4,5),original,work.target());assertTrue(result.getBoolean("ok"));work.completed();JSONObject receipt=f.tasks.inferenceUsage(work.reference().getString("taskId")).getJSONArray("receipts").getJSONObject(0);assertEquals("COMPLETED",receipt.getString("outcome"));assertEquals("CONNECTION_TEST",receipt.getJSONObject("context").getString("purpose"));assertEquals(3,receipt.getJSONObject("usage").getJSONObject("counters").getJSONObject("TOTAL").getLong("value"));assertEquals(1,posts.get());
  }}finally{server.stop(0);worker.shutdownNow();assertTrue(worker.awaitTermination(5,TimeUnit.SECONDS));}
 }}
 @Test public void actualRealtimeProtocolSeparatesAsrAndReplyInTheSameNativeSqlSession()throws Exception{try(Fixture f=new Fixture()){
  RealtimeVoiceProfile selected=new RealtimeVoiceProfile("wss://voice.example.invalid/realtime","speech-model","alloy","asr-model",2);try(RealtimeInferenceAccounting accounting=RealtimeInferenceAccounting.open(f.tasks,selected,"native-private-voice-key",id())){
   java.util.List<JSONObject> sent=new java.util.ArrayList<>();PcmPlaybackQueue queue=new PcmPlaybackQueue("native-session",()->{throw new AssertionError("no audio output expected in usage-only protocol fixture");},event->{});
   OpenAiRealtimeProtocol protocol=new OpenAiRealtimeProtocol(selected,queue,new OpenAiRealtimeProtocol.Output(){public void send(JSONObject event){sent.add(event);}public void ready(){}public void changed(String status){}public void responseCreated(JSONObject actual)throws Exception{accounting.created(actual);}public void responseDone(JSONObject actual)throws Exception{accounting.done(actual);}public void transcriptionCommitted(JSONObject actual)throws Exception{accounting.transcriptionCommitted(actual);}public void transcriptionFinished(JSONObject actual)throws Exception{accounting.transcriptionFinished(actual);}});
   protocol.opened();protocol.receive(new JSONObject().put("type","session.updated").put("session",sent.get(0).getJSONObject("session")).toString());protocol.appendInput(new byte[960]);
   protocol.receive(new JSONObject().put("type","input_audio_buffer.committed").put("event_id","commit_one").put("item_id","item_same").toString());
   protocol.receive(new JSONObject().put("type","response.created").put("response",new JSONObject().put("id","response_same")).toString());protocol.receive(new JSONObject().put("type","response.done").put("response",response("response_same").put("output",new JSONArray())).toString());
   JSONObject transcription=new JSONObject().put("type","conversation.item.input_audio_transcription.completed").put("event_id","asr_done").put("item_id","item_same").put("content_index",0).put("transcript","TRANSCRIPT-MUST-NOT-PERSIST").put("usage",new JSONObject().put("type","tokens").put("input_tokens",13).put("output_tokens",9).put("total_tokens",22));protocol.receive(transcription.toString());protocol.receive(transcription.toString());
   JSONObject usage=f.tasks.inferenceUsage(accounting.reference().getString("taskId"));assertEquals(2,usage.getInt("attempts"));assertEquals(2,usage.getInt("completed"));assertEquals(2,usage.getJSONArray("groups").length());java.util.Set<String> purposes=new java.util.HashSet<>(),calls=new java.util.HashSet<>();for(int i=0;i<2;i++){JSONObject receipt=usage.getJSONArray("receipts").getJSONObject(i);calls.add(receipt.getString("callId"));purposes.add(receipt.getJSONObject("context").getString("purpose"));if("REALTIME_TRANSCRIPTION".equals(receipt.getJSONObject("context").getString("purpose"))){assertEquals("server_transcription_observed",receipt.getJSONObject("route").getString("requestOrigin"));assertEquals("asr-model",receipt.getJSONObject("route").getString("requestedModel"));assertEquals(22,receipt.getJSONObject("usage").getJSONObject("counters").getJSONObject("TOTAL").getLong("value"));}}
   assertEquals(java.util.Set.of("REALTIME","REALTIME_TRANSCRIPTION"),purposes);assertEquals(2,calls.size());assertFalse(f.tasks.get(accounting.reference().getString("taskId"),false).toString().contains("TRANSCRIPT-MUST-NOT-PERSIST"));protocol.close();queue.close();
  }
 }}
 @Test public void missingAsrUsageIsNotBorrowedFromReplyAndSameItemInAnotherSessionIsIndependent()throws Exception{try(Fixture f=new Fixture()){
  RealtimeVoiceProfile selected=new RealtimeVoiceProfile("wss://voice.example.invalid/realtime","speech-model","alloy","asr-model",2);String firstCall="";for(int n=0;n<2;n++)try(RealtimeInferenceAccounting accounting=RealtimeInferenceAccounting.open(f.tasks,selected,"native-private-key",id())){
   accounting.transcriptionCommitted(new JSONObject().put("item_id","item_same"));JSONObject done=new JSONObject().put("type","conversation.item.input_audio_transcription.completed").put("item_id","item_same").put("content_index",0).put("transcript","owner words");accounting.transcriptionFinished(done);accounting.transcriptionFinished(new JSONObject(done.toString()));JSONObject usage=f.tasks.inferenceUsage(accounting.reference().getString("taskId"));assertEquals(1,usage.getInt("attempts"));JSONObject receipt=usage.getJSONArray("receipts").getJSONObject(0);assertTrue(receipt.getJSONObject("usage").getJSONObject("counters").getJSONObject("TOTAL").isNull("value"));assertEquals("REALTIME_TRANSCRIPTION",receipt.getJSONObject("context").getString("purpose"));if(n==0)firstCall=receipt.getString("callId");else assertNotEquals(firstCall,receipt.getString("callId"));
  }
 }}
}
